            return d
    return None
def _ok(d):
    return isinstance(d, dict) and (d.get('ok') is True or str(d.get('ok')).lower() == 'true')
def _today():
    return str(_v().get('now') or '')[:10]
def _status(c):
    t = _today()
    f = str(c.get('valid_from') or '')[:10]
    e = str(c.get('valid_to') or '')[:10]
    if not t or not f or not e:
        return 'unknown'
    if t < f:
        return 'not_started'
    if t > e:
        return 'expired'
    return 'active'
'''

